namespace boost {
    namespace fusion {
        namespace detail
        {





            template <typename Sequence, typename Nil_ = fusion::nil_>
            struct segmented_end
            {
                typedef
                    segmented_iterator<
                    typename segmented_end_impl<Sequence, Nil_>::type
                    >
                    type;

                constexpr
                    static type call(Sequence& seq)
                {
                    return type(
                        segmented_end_impl<Sequence, Nil_>::call(seq, Nil_()));
                }
            };

        }
    }
}

