namespace boost {
    namespace fusion
    {
        struct mpl_sequence_tag;

        namespace extension
        {
            template <typename Tag>
            struct end_impl;

            template <>
            struct end_impl<mpl_sequence_tag>
            {
                template <typename Sequence>
                struct apply
                {
                    typedef typename mpl::end<
                        typename remove_const<Sequence>::type
                    >::type iterator;
                    typedef mpl_iterator<iterator> type;

                    constexpr
                        static type
                        call(Sequence)
                    {
                        return type();
                    }
                };
            };
        }
    }
}

