        template <bool use_default_constructor> struct swap_selector;

        template <>
        struct swap_selector<true>
        {
            template <class T>
            static void optional_swap(optional<T>& x, optional<T>& y)
            {
                const bool hasX = !!x;
                const bool hasY = !!y;

                if (!hasX && !hasY)
                    return;

                if (!hasX)
                    x.emplace();
                else if (!hasY)
                    y.emplace();


                boost::core::invoke_swap(x.get(), y.get());

                if (!hasX)
                    y = boost::none;
                else if (!hasY)
                    x = boost::none;
            }
        };









