namespace boost {
    namespace fusion
    {
        struct mpl_sequence_tag;

        namespace extension
        {
            template<typename Tag>
            struct at_impl;

            template <>
            struct at_impl<mpl_sequence_tag>
            {
                template <typename Sequence, typename N>
                struct apply
                {
                    typedef typename mpl::at<Sequence, N>::type type;

                    constexpr
                        static type
                        call(Sequence)
                    {
                        return type();
                    }
                };
            };
        }
    }
}

