namespace boost {
    namespace mpl {




        template< typename Tag >
        struct erase_impl
        {
            template<
                typename Sequence
                , typename First
                , typename Last
            >
                struct apply
            {
                typedef typename if_na< Last, typename next<First>::type >::type last_;


                typedef iterator_range<
                    typename begin<Sequence>::type
                    , First
                > first_half_;


                typedef iterator_range<
                    last_
                    , typename end<Sequence>::type
                > second_half_;

                typedef typename reverse_fold<
                    second_half_
                    , typename clear<Sequence>::type
                    , push_front<_, _>
                >::type half_sequence_;

                typedef typename reverse_fold<
                    first_half_
                    , half_sequence_
                    , push_front<_, _>
                >::type type;
            };
        };

    }
}

