            template <typename Stream, typename Tag, typename T>
            struct stream_data
            {
                struct arena
                {
                    ~arena()
                    {
                        for (
                            typename std::vector<T*>::iterator i = data.begin()
                            ; i != data.end()
                            ; ++i)
                        {
                            delete* i;
                        }
                    }

                    std::vector<T*> data;
                };

                static void attach(Stream& stream, T const& data)
                {
                    static arena ar;
                    ar.data.push_back(new T(data));
                    stream.pword(get_xalloc_index<Tag>(stream.xalloc)) = ar.data.back();
                }

                static T const* get(Stream& stream)
                {
                    return (T const*)stream.pword(get_xalloc_index<Tag>(stream.xalloc));
                }
            };


