namespace boost {
    namespace spirit {
        namespace qi
        {
            namespace detail
            {
                template<typename Char>
                inline void token_printer(std::ostream& o, Char c)
                {

                    spirit::traits::print_token(o, c);
                }
            }

            struct simple_trace
            {
                int& get_indent() const
                {
                    static int indent = 0;
                    return indent;
                }

                void print_indent(int n) const
                {
                    n *= 2;
                    for (int i = 0; i != n; ++i)
                        std::cerr << ' ';
                }

                template <typename Iterator>
                void print_some(
                    char const* tag
                    , int
                    , Iterator first, Iterator const& last) const
                {
                    print_indent(get_indent());
                    std::cerr << '<' << tag << '>';
                    int const n = 20;
                    for (int i = 0; first != last && i != n && *first; ++i, ++first)
                        detail::token_printer(std::cerr, *first);
                    std::cerr << "</" << tag << '>' << std::endl;



                }

                template <typename Iterator, typename Context, typename State>
                void operator()(
                    Iterator const& first
                    , Iterator const& last
                    , Context const& context
                    , State state
                    , std::string const& rule_name) const
                {
                    switch (state)
                    {
                    case pre_parse:
                        print_indent(get_indent()++);
                        std::cerr
                            << '<' << rule_name << '>'
                            << std::endl;
                        print_some("try", get_indent(), first, last);
                        break;
                    case successful_parse:
                        print_some("success", get_indent(), first, last);
                        print_indent(get_indent());
                        std::cerr
                            << "<attributes>";
                        traits::print_attribute(
                            std::cerr,
                            context.attributes
                        );
                        std::cerr
                            << "</attributes>";
                        if (!fusion::empty(context.locals))
                            std::cerr
                            << "<locals>"
                            << context.locals
                            << "</locals>";
                        std::cerr << std::endl;
                        print_indent(--get_indent());
                        std::cerr
                            << "</" << rule_name << '>'
                            << std::endl;
                        break;
                    case failed_parse:
                        print_indent(get_indent());
                        std::cerr << "<fail/>" << std::endl;
                        print_indent(--get_indent());
                        std::cerr
                            << "</" << rule_name << '>'
                            << std::endl;
                        break;
                    }
                }
            };
        }
    }
}

